Let $A\geq 1$ be fixed. Let $h:\mathbb{N}\to \mathbb{R}_{\geq 0}$ be a multiplicative function that satisfies $h(n)\leq n^{o(1)}$ and $h(p^k)\leq A^k$ for all primes $p$ and all $k\in \mathbb{N}$. Let $\log N\leq P'_1,P'_2,P'_3 \leq N$. Then, for any $m\in [5N/4,7N/4]$ and $m \equiv 4\hspace{-0.12cm}\hspace{-0.12cm}\hspace{-0.12cm}\hspace{-0.12cm}\pmod {6}$, we have
	\begin{align}
		&\sum_{N/2< n\leq N}h(n)(\tau^2r_{P'_1})(n+2)(\tau^2r_{P'_2})(m-n)(\tau^2r_{P'_3})(m-n+2)\\
		\ll& \frac{N}{\log N}\mathfrak{S}(m) \prod_{i=1}^3  \left(\frac{\log N}{\log P'_i}\right)^{3} \prod_{p<N}\left(1+\frac{h(p)}{p}\right)\prod_{\substack{p\mid m (m+2)(m+4)\\ p\geq \min\{P'_1,P'_2,P'_3\}}}\Bigl(1+\frac{O(1)}{p}\Bigr).
	\end{align}
    The same bound holds if $h(n)$ swaps places with any of the other weights on $n+2,m-n,m-n+2$.

Let $\exp((\log N)^{1/2})\leq R^{40}\leq P\leq N^{1/5}$, and
    let $\Lambda^*\in \{\Lambda, \Lambda_{E_3^*}\}$. There exists an arithmetic function $E$  such that the following hold.
	\begin{enumerate}
	   \item If there is no exceptional zero of level $R^2$ and quality $\kappa$, then we have
		\begin{align}
		  \|\Lambda^{*}-r_{P}-E\|_{\infty}^{\wedge}\ll N R^{-1/3}
		\end{align}
	    and
	   \begin{align}
              |E(n)|&\ll H_R(n) \Bigl(\frac{\log N}{\log P}\exp\bigl(-c\frac{\log P}{\log R} \bigr)+\exp\bigl( -c \kappa \frac{\log N}{\log R} -c \frac{\log N}{\log P}\bigr)\Bigr).
	   \end{align}
		\item If there is an exceptional zero $\widetilde{\beta}$ of level $R^2$, then if $\widetilde{\chi}$ is the exceptional character, we have
			\begin{align}
				\|\Lambda^{*}-r_P(1-(\cdot)^{\widetilde{\beta}-1}\widetilde{\chi})+E\|_{\infty}^{\wedge}\ll N (R^{-1/3}\widetilde{r}^{1/2}+R^{-1+o(1)}\widetilde{r}^{3/2}).
			\end{align}
             Here $E$ satisfies again~(7.22), and now additionally  
	       \begin{align}	
              \mathbf{1}_{\widetilde{\chi}(n)=1}|E(n)|&\ll H_R(n) (1-\widetilde{\beta})(\log N)\left( \frac{\log N}{\log P}\exp\bigl(-c\frac{\log P}{\log R} \bigr)+\exp\bigl(-c\frac{\log N}{\log P}\bigr)\right).
			\end{align}
	\end{enumerate}

Let $\exp((\log N)^{1/2})\leq R^{40}\leq P\leq N^{1/5}$ and assume that there is no exceptional zero of level $R^2$ and quality $\kappa$ (see Definition~7.1). Let $h_\xi$ be the multiplicative function supported on square-free integers only and given on the primes by 
 \begin{align*}
        h_{\xi}(p)=\min\Bigl\{1,10(1+|\xi|)\frac{\log p}{\log R} \Bigr\},
    \end{align*}
and let 
\begin{align*}
    H_R(n)=\tau(n)(\log R) \int_{\mathbb{R}} \frac{h_{\xi}(n)}{(1+|\xi|)^{10}}\,\mathrm{d} \xi.
\end{align*}
There exists an arithmetic function $E$ and a constant $c>0$ such that the following holds. We have
		\begin{align*}
		  \sup_{\alpha \in {\mathbb R}} \bigl| \sum_{N/2<n\leq N}(\Lambda(n)-r_{P}(n)-E(n))e(\alpha n) \bigr| \ll N R^{-1/3}
		\end{align*}
	    and
	   \begin{align*}
          |E(n)|&\ll H_R(n) \Bigl(\exp\bigl( -c \kappa \frac{\log N}{\log R} -c \frac{\log N}{\log P}\bigr)+\frac{\log N}{\log P}\exp\bigl(-c\frac{\log P}{\log R} \bigr)\Bigr).
	   \end{align*}

Let $P_0=N^{\delta_1},R_0=N^{\delta_1^3},P_1=N^{\delta_1^4},D_1=N^{\delta_1^3/100},$  and let $\lambda$ be the constant from Lemma~7.2. Let $f\in\{\omega,\Omega\}$ be a pre-sieve as in Definition~2.2.
	Assume there is no exceptional zero of level $R_0^2$ and quality $\lambda \delta_1^2$. Then, for any $\epsilon \gg e^{-c \delta_1^{-1/2}}$, we have
		\begin{align*}
			\Lambda(n)f(n+2)&\approx_{\epsilon} r_{P_0}(n) f(n+2),\\
			f(n)\Lambda_{E_3^*}(n+2)&\approx_{\epsilon} f(n)r_{P_0}(n+2).
		\end{align*}

Let $P_0=N^{\delta_1},R_0=N^{\delta_1^3},P_1=N^{\delta_1^4},D_1=N^{\delta_1^3/100},$ $\lambda$ the constant from Lemma~7.2 and let $f\in\{\omega,\Omega\}$ be a pre-sieve as in Definition~2.2. Assume that $\widetilde{\chi}$ is the exceptional character with exceptional zero $\widetilde{\beta}$ of quality $\lambda \delta_1^2$ and level $R_0^2$. Then for any $\epsilon>e^{-c \delta_1^{-1/2}}$, we have
    \begin{align*}
	   \mathbf{1}_{\widetilde{\chi}(n)=-1}\Lambda(n)f(n+2)&\approx_{\epsilon}  \mathbf{1}_{\widetilde{\chi}(n)=-1}(1+n^{\widetilde{\beta}-1}) r_{P_0}(n)f(n+ 2),\\
	   \mathbf{1}_{\widetilde{\chi}(n)=-1}f(n)\Lambda_{E_3^*}(n+2)&\approx_{\epsilon} c_{E_3^*}  \mathbf{1}_{\widetilde{\chi}(n)=-1}f(n)(1-\widetilde{\chi}(n+2)n^{\widetilde{\beta}-1})r_{P_0}(n+2).
	\end{align*}
	Further, for $\widetilde{\epsilon}>(1-\widetilde{\beta})(\log N)e^{-c \delta_1^{-1/2}}$, it holds that
	\begin{align*}
		\mathbf{1}_{\widetilde{\chi}(n)=\widetilde{\chi}(n+2)=1}\Lambda(n)f(n+2)&\approx_{\widetilde{\epsilon}} \mathbf{1}_{\widetilde{\chi}(n)=\widetilde{\chi}(n+2)=1}(1-n^{\widetilde{\beta}-1} )r_{P_0}(n)f(n+2),\\
		\mathbf{1}_{\widetilde{\chi}(n)=\widetilde{\chi}(n+2)=1}f(n)\Lambda_{E_3^*}(n+2)&\approx_{\widetilde{\epsilon}} \mathbf{1}_{\widetilde{\chi}(n)=\widetilde{\chi}(n+2)=1}(1-n^{\widetilde{\beta}-1})f(n) r_{P_0}(n+2) .
	\end{align*}

Let $P_1=N^{\delta_1^4},R_0=N^{\delta_1^3}$ and $\lambda$ the constant from Lemma~7.2.
		Assume that there exists no exceptional zero of level $R_0^2$ and quality $\lambda\delta_1^2$. There exists $c_1>0$ such that for $\epsilon = e^{-c \delta_1^{-1/2}}$ we have 
			\begin{align}
				 \Lambda(n)\Lambda_2(n+2)&\gtrapprox_{\epsilon} c_1  r_{P_1}(n)r_{P_1}(n+2).
			\end{align}

Let $P_1=N^{\delta_1^4},R_0=N^{\delta_1^3}$ and $\lambda$ the constant from Lemma~7.2.
				Assume that there exists an exceptional character $\widetilde{\chi}$ with exceptional zero $\widetilde{\beta}$ of level $R_0^2$ and quality $\lambda\delta_1^2$. There exist $c_1>0$ such that the following holds. Let 
				\begin{align*}
					\epsilon = e^{-c \delta_1^{-1/2}},\quad 
					\widetilde{\epsilon}=\epsilon (1-\widetilde{\beta}) \log N.
				\end{align*}
				We have
				\begin{align}
					\mathbf{1}_{\widetilde{\chi}(n)=-1}  \Lambda(n)\Lambda_2(n+2)&\gtrapprox_{\epsilon} c_1 \mathbf{1}_{\widetilde{\chi}(n)=-1} r_{P_1}(n)r_{P_1}(n+2)\\
					\mathbf{1}_{\widetilde{\chi}(n)=\widetilde{\chi}(n+2)=1}\Lambda(n)\Lambda_2(n+2)&\gtrapprox_{\widetilde{\epsilon}} c_1 (1-\widetilde{\beta}) (\log N) \mathbf{1}_{\widetilde{\chi}(n)=\widetilde{\chi}(n+2)=1} r_{P_1}(n)r_{P_1}(n+2).  
				\end{align}

Assume that $N$ is sufficiently large, and let $P_1=N^{\delta_1^4}$. There exist main-sieves 
\begin{align*}
    \omega_{\textnormal{M}}(n)&=\sum_{d\mid n}\lambda^\omega_{\textup{M}}(d),\\
    \Omega_{\textnormal{M}}(n)&=\sum_{d\mid n}\lambda^\Omega_{\textup{M}}(d),\\
    \Omega'_{\textnormal{M}}(n)&=\sum_{d\mid n}\lambda^{\Omega'}_{\textup{M}}(d),
\end{align*}
as in Definition~2.3, and an error function $E(n)$ such that the following three statements hold. 
\begin{enumerate}[label=(\roman*)]
\item Let $\omega,\Omega$ be pre-sieves as in Definition~2.2 and denote
\begin{align*}
    g_1(n)&=\Lambda(n)\Omega(n+2)\omega_{\textnormal{M}}(n+2), \\
    g_2(n)&=(3/5+\delta_1)c_{E_3^*}\Omega(n)\Omega_{\textnormal{M}}(n)\Lambda_{E_3^*}(n+2), \\
    g_3(n)&=\Lambda(n)\bigl(\omega -\Omega\bigr)(n+2)\Omega'_{\textnormal{M}}(n+2).
\end{align*}
We have for $N/2< n\leq N$ the inequality
\begin{align}
    \Lambda(n)\Lambda_2(n+2)\geq g_1(n)-g_2(n)+g_3(n)+\Lambda(n)E(n+2).
\end{align}
    \item The sieve weights fulfil
    \begin{align}
     \prod_{P_1\leq p < N^{1/10}}\left(1-\frac{1}{p}\right)^{-1} \left(\sum_{d}\frac{\lambda^{\Omega'}_{\textup{M}}(d)}{\varphi(d)}\right)\ll 1,
    \end{align}
    and, if $\delta_1$ is sufficiently small, there exists an absolute constant $c_0>0$ such that
\begin{align}
   \prod_{P_1\leq p < N^{1/10}}\left(1-\frac{1}{p}\right)^{-1} \left(\sum_{d}\frac{\lambda^\omega_{\textup{M}}(d)}{\varphi(d)}-(3/5+\delta_1) c_{E_3^*}\sum_{d}\frac{\lambda^\Omega_{\textup{M}}(d)}{\varphi(d)}\right)\geq c_0.
\end{align}

\item We have the approximation
\begin{align} 
    \Lambda(n)E(n+2)\approx_{N^{-1/100}} 0
\end{align}
in the sense of Definition~2.4.

\end{enumerate}

Assume the following conditions.
 \begin{itemize}
        \item $\Lambda^* \in \{\Lambda,\Lambda_{E_3^*},r_{P_1} \}$ with $P_1=N^{\delta_1^4}$. 
        \item $f_\textup{M}(n)=\sum_{d\mid n}\lambda_{\mathrm{M}}(d)$ is a main-sieve as in Definition~2.3.
        \item  $f_{\textup{Pre}} \in \{\omega,\Omega\}$ is a pre-sieve.
    \end{itemize}
    Let $\epsilon \geq N^{-(\delta_1/10)^{4}}$.
		Then we have
		\begin{align*}
			\Lambda^*(n)f_{\textup{M}}(n+2) f_{\textup{Pre}}(n+2)\approx_{\epsilon} \left(\prod_{P_1\le p < N^{1/10}} \left(1-\frac{1}{p}\right)^{-1} \sum_{d}\frac{\lambda_{\mathrm{M}}(d)}{\varphi(d)}\right) \Lambda^*(n)f_{\textup{Pre}}(n+2)
		\end{align*}
		and similarly with the roles of $n$ and $n+2$ reversed.     
		Let further $\chi$ be a primitive quadratic character with conductor at most $\widetilde{R}=N^{2\delta_1^5}$ and let $\mathfrak{c}(n)=  \mathbf{1}_{\chi(n)=-1} $ or $\mathfrak{c}(n)=\mathbf{1}_{\chi(n)=\chi(n+2)=1}$. Expanding these indicators into characters via $\mathbf{1}_{\chi(n)=-1}=\tfrac12(1-\chi(n))$ and $\mathbf{1}_{\chi(n)=\chi(n+2)=1}=\tfrac14(1+\chi(n))(1+\chi^{+}(n))$ produces the four twists $\mathfrak b\in\{1,\chi,\chi^{+},\chi\chi^{+}\}$ met below.
		We have
		\begin{align*}
			\mathfrak{c}(n) \Lambda^*(n)f_{\textup{M}}(n+2)f_{\textup{Pre}}(n+2)\approx_{\epsilon} \mathfrak{c}(n)\left(\prod_{P_1\le p < N^{1/10}} \left(1-\frac{1}{p}\right)^{-1}\sum_{d}\frac{\lambda_{\mathrm{M}}(d)}{\varphi(d)}\right) \Lambda^*(n) f_{\textup{Pre}}(n+2)
		\end{align*}
		and similarly with the roles of $n$ and $n+2$ reversed.

For $1\leq i \leq 4$, let the functions $f_i\in \{ \omega, \Omega \}$ be pre-sieves as in Definition~2.2. For any natural number $m$ and any $1\leq X\leq m$, we have
    \begin{align}\begin{aligned}
	   &\sum_{n\leq X} f_1(n)f_2(n+2) f_3(m-n)f_4(m-n+2)\\
       =& X \mathfrak{S}(m)\left(1+ O\left(e^{-\frac{\log D_1}{10 \log P_1}}+\frac{\log m}{P_1 }\right)\right)+O(D_1^4 (\log P_1)^4).
       \end{aligned}
	\end{align}

For $1\leq i \leq 4$, let the functions $f_i\in \{ \omega, \Omega \}$ be pre-sieves as in Definition~2.2. Let  $\chi$ be a primitive quadratic character to the modulus $r
 \geq 3$. There exist functions $\sigma_1, \sigma_2\colon \mathbb{N}\to [-1,1]$ (depending on $\chi$) --- they are real since $\chi$ is real-valued --- with $|\sigma_1|,|\sigma_2|\leq 1$ such that for any $1\leq X\leq m$, we have
    \begin{align}
          &\sum_{n\leq X} \mathbf{1}_{\chi(n)=\chi(m-n)=-1}\mathbf{1}_{(n+2,r)=(m-n+2,r)=1} f_1(n)f_2(n+2) f_3(m-n)f_4(m-n+2)\\
		=& X \mathfrak{S}(m)\left(\frac{1+\sigma_1(m)}{4}+O_{\epsilon}(r^{-1+\epsilon})\right)\left(1+ O\left(e^{- \frac{\log D_1}{10 \log P_1}}+\frac{\log m}{P_1}\right)\right)+O(rD_1^4(\log P_1)^4) 
        \end{align}
        and
        \begin{align}
		  &\sum_{n\leq X} \mathbf{1}_{\chi(n)=\chi(n+2)=1}\mathbf{1}_{\chi(m-n)=-1} \mathbf{1}_{(m-n+2,r)=1} f_1(n)f_2(n+2) f_3(m-n)f_4(m-n+2)\\
		 =& X\mathfrak{S}(m)\left(\frac{1-\sigma_1(m)-\sigma_2(m)}{8}+O_{\epsilon}(r^{-1/2+\epsilon})\right)\bigl(1+ O(e^{- \frac{\log D_1}{10 \log P_1}}+\frac{\log m}{P_1})\bigr)+O(rD_1^4(\log P_1)^4).
	\end{align}
